var PM_POOL={
  w:[{k:'solo',goal:10,txt:'싱글 10판 하기',p:400},{k:'arena',goal:5,txt:'대전 5판 하기',p:450},{k:'eat',goal:500,txt:'물고기 500마리 먹기',p:450},
     {k:'pearl',goal:2500,txt:'진주 2,500개 모으기',p:400},{k:'camp',goal:5,txt:'심해 탐험 5번 깨기',p:500},{k:'top3',goal:3,txt:'대전에서 3위 안에 3번 들기',p:500},{k:'day',goal:5,txt:'5일 접속하기',p:400}],
  m:[{k:'day',goal:20,txt:'20일 접속하기',p:1500},{k:'eat',goal:2500,txt:'물고기 2,500마리 먹기',p:1500},{k:'solo',goal:40,txt:'싱글 40판 하기',p:1500},
