var PM_BONUS={w:5,m:15},PM_N=4,DMV={tab:'d'};
function pmId(t){var d=new Date();if(t==='m')return d.getFullYear()+'-'+(d.getMonth()+1);d.setDate(d.getDate()-((d.getDay()+6)%7));return d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate()}
function pmDef(t,k){var L=PM_POOL[t];for(var i=0;i<L.length;i++)if(L[i].k===k)return L[i];return null}
function pmEnsure(t){if(!save.pm)save.pm={};var id=pmId(t),M=save.pm[t];if(M&&M.id===id&&M.ids&&M.ids.length)return M;
  var h=7,i;for(i=0;i<id.length;i++)h=(h*31+id.charCodeAt(i))>>>0;var ks=PM_POOL[t].map(function(o){return o.k}),ids=[];
  while(ids.length<PM_N&&ks.length){h=(h*1103515245+12345)>>>0;ids.push(ks.splice((h>>>8)%ks.length,1)[0])}
  M=save.pm[t]={id:id,ids:ids,v:{},got:{},all:false};persist();return M}
function pmAdd(k,v){if(!(v>0))return;['w','m'].forEach(function(t){var M=pmEnsure(t);if(M.ids.indexOf(k)<0)return;var o=pmDef(t,k),was=M.v[k]||0;M.v[k]=was+v;
  if(was<o.goal&&M.v[k]>=o.goal)setTimeout(function(){banner(t==='w'?T('주간 미션 완료!'):T('월간 미션 완료!'),T(o.txt)+T(' · 미션 창에서 받아요'))},1300)})}
function pmReady(t){var M=pmEnsure(t),c=0;M.ids.forEach(function(k){if(!M.got[k]&&(M.v[k]||0)>=pmDef(t,k).goal)c++});if(!M.all&&M.ids.every(function(k){return M.got[k]}))c++;return c}
function dmTodayReady(){var M=dmEnsure(),c=0;if(save.att&&save.att.last===today()&&!save.att.claim)c++;M.ids.forEach(function(k){if(!M.got[k]&&(M.v[k]||0)>=dmDef(k).goal)c++});if(!M.all&&M.ids.every(function(k){return M.got[k]}))c++;return c}
function dmLeft(t){var n=new Date(),e=new Date(n.getFullYear(),n.getMonth(),n.getDate()+1);if(t==='w')e.setDate(e.getDate()+(7-((n.getDay()+6)%7)-1));if(t==='m')e=new Date(n.getFullYear(),n.getMonth()+1,1);
  var ms=e-n,d=Math.floor(ms/864e5),h=Math.floor(ms%864e5/36e5),m=Math.floor(ms%36e5/6e4);
  if(LANG==='en')return 'Resets in '+(d?d+'d ':'')+(d||h?h+'h':m+'m');return (d?d+T('일 '):'')+(d||h?h+T('시간'):m+T('분'))+T(' 뒤 새로 바뀌어요')}
