  time:'<circle cx="12" cy="13" r="7.5" stroke="currentColor" stroke-width="2.4" fill="none"/><path d="M12 9v4l3 2M10 3h4" stroke="currentColor" stroke-width="2.4" fill="none" stroke-linecap="round"/>',
  camp:'<path d="M12 4v15M7 15c0 3 2 5 5 5s5-2 5-5M8 8h8" stroke="currentColor" stroke-width="2.4" fill="none" stroke-linecap="round"/><circle cx="12" cy="4.5" r="1.8" fill="currentColor"/>',
