function dmEl(t,c,tx){var e=document.createElement(t);if(c)e.className=c;if(tx!=null)e.textContent=tx;return e}
function dmProgTxt(k,v,g){return k==='deep'?v+'m / '+g+'m':k==='time'?fmtTime(v)+' / '+fmtTime(g):nf(v)+' / '+nf(g)}
function dmGive(o){if(o.g)save.gems=(save.gems||0)+o.g;else save.pearls+=o.p}
/* 미션 한 줄: 아이콘 · 이름 · 진행 막대 · 보상(받기 버튼) */
function dmRow(k,o,v,got,onGet){var ok=!got&&v>=o.goal,li=dmEl('li','dmc '+(got?'got':ok?'ok':'run'));
  var ic=dmEl('i','dmi');ic.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true">'+(DM_ICO[k]||DM_ICO.solo)+'</svg>';li.appendChild(ic);
  var tx=dmEl('div','dmt');tx.appendChild(dmEl('strong','',T(o.txt)));var pr=dmEl('small','',dmProgTxt(k,Math.min(v,o.goal),o.goal));tx.appendChild(pr);
  var bar=dmEl('i','dmbar'),fl=dmEl('u');fl.style.width=Math.round(Math.min(v,o.goal)/o.goal*100)+'%';bar.appendChild(fl);tx.appendChild(bar);li.appendChild(tx);
