function dmSort(list){var r={ok:0,run:1,got:2};return list.sort(function(a,b){return r[a.st]-r[b.st]})}
/* 보너스 칸: 모두 받으면 보석 */
function dmBonus(n,tot,done,g,lab,onGet){var w=dmEl('div','dmbonus'+(done?' done':n>=tot?' ok':''));var dots=dmEl('span','dmdots');for(var i=0;i<tot;i++)dots.appendChild(dmEl('i',i<n?'on':''));
