  var b=dmEl('button','dmb gem');b.type='button';if(done){b.textContent=T('받음');b.disabled=true}else{if(n>=tot)b.appendChild(dmEl('b','',T('받기')));b.appendChild(dmEl('span','rg',String(g)));b.disabled=n<tot;b.addEventListener('click',function(){onGet();buzz(30);refreshHome(true);dmOpen()})}
