  for(i=0;i<3;i++){var rx=W*(.12+.34*i)+Math.sin(tt*.4+i)*12,lg=c.createLinearGradient(0,0,0,Hh*.8);lg.addColorStop(0,'rgba(255,255,255,'+(.2*(1-dk)).toFixed(3)+')');lg.addColorStop(1,'rgba(255,255,255,0)');c.fillStyle=lg;c.beginPath();c.moveTo(rx,0);c.lineTo(rx+W*.1,0);c.lineTo(rx+W*.1+Hh*.3,Hh*.8);c.lineTo(rx+Hh*.3,Hh*.8);c.closePath();c.fill()}
  for(i=0;i<14;i++){var bx=(i*.137%1)*W+Math.sin(tt+i)*6,by=Hh-((tt*34+i*67)%Hh);c.beginPath();c.arc(bx,by,1.5+i%3,0,7);c.strokeStyle='rgba(255,255,255,.45)';c.lineWidth=1.2;c.stroke()}
  function fish(L,x,y,s,ang,o){try{if(o&&o.deco)drawFishDeco(c,null,x,y,s,ang,L,{phase:tt*2,px:s,minLw:1.2});else drawFish(c,x,y,s,ang,L,Object.assign({phase:tt*2,px:s,minLw:1.2},o||{}))}catch(e){}}
  function label(txt,x,y,col,sz){c.font=(sz||17)+'px "Black Han Sans", Jua, sans-serif';c.textAlign='center';c.textBaseline='middle';c.lineJoin='round';c.lineWidth=5;c.strokeStyle='#0B2C4A';c.strokeText(txt,x,y);c.fillStyle=col||'#FFFFFF';c.fillText(txt,x,y)}
