    if(tt<2.1){c.save();c.translate(ex,ey);c.rotate(wob);c.globalAlpha=tt<1.8?1:1-(tt-1.8)/.3;c.beginPath();c.ellipse(0,0,er*.85,er,0,0,7);var eg=c.createRadialGradient(-er*.3,-er*.4,er*.1,0,0,er);eg.addColorStop(0,'rgba(255,255,255,.95)');eg.addColorStop(1,'rgba(255,214,170,.75)');c.fillStyle=eg;c.fill();c.lineWidth=2.5;c.strokeStyle='#0B2C4A';c.stroke();
      c.beginPath();c.arc(0,er*.1,er*.28,0,7);c.fillStyle='rgba(40,60,80,.45)';c.fill();if(tt>1.2){c.beginPath();c.moveTo(-er*.5,-er*.2);c.lineTo(-er*.2,0);c.lineTo(0,-er*.25);c.lineTo(er*.25,0);c.lineTo(er*.5,-er*.2);c.lineWidth=2.5;c.stroke()}c.restore();c.globalAlpha=1}
    if(tt>1.8){var q=Math.min(1,(tt-1.8)/.6),fx2=ex+Math.sin((tt-1.8)*1.3)*W*.18,fy2=ey+Math.sin((tt-1.8)*2.1)*S*.5;ring(ex,ey,er*(1+q*2),1-q);fish(me,fx2,fy2,S*.55*q+S*.1,Math.cos((tt-1.8)*1.3)>0?0:Math.PI,{deco:1});
