  }else if(k===1){ /* 먹고 자라기 */
    var n=Math.min(3,Math.floor(tt/1.4)),sc=1+.28*n,mx=W*.3+Math.min(1,tt/4.2)*W*.25,my=cy0+Math.sin(tt*2)*6,cm=[1.0,1.6,2.4,3.2][n];
    var prey=[onbFish('clownfish'),onbFish('goldfish'),onbFish('neon')];
    for(i=n;i<3;i++){var px=W*.62+i*W*.14-Math.min(1,tt/4.2)*W*.12,py=cy0+(i-1)*S*.9+Math.sin(tt*3+i)*5;fish(prey[i],px,py,S*.38*(1+.25*i),Math.PI)}
    var ph=tt-n*1.4;if(n>0&&ph<.6){ring(mx+S*sc*.8,my,S*(.4+ph*1.2),1-ph/.6);label(T('꺼-억!'),mx+S*.6*sc*1.3,my-S*.6*sc-18-ph*20,'#FFE45C',18)}
    fish(me,mx,my,S*.6*sc,0,{deco:1});label(T('나')+' · '+cm.toFixed(1)+'cm',mx,my+S*.6*sc*.9+16,'#FFE45C',16);
  }else if(k===2){ /* 큰 물고기 입 피하고 꼬리 물어뜯기 */
