#upd{z-index:44}#news{z-index:43}#modePick,#camp{z-index:41}#campRes{z-index:40}.updpanel{max-width:420px}
#svUp{z-index:46}#svRes{z-index:40}
.mpick>.mcard.surv{grid-column:1/-1}
.mcard.surv{background:linear-gradient(180deg,#FFC9D6,#FF7A9A)}
.mcard .mcbeta{position:absolute;top:10px;right:14px;font-style:normal;font-family:"Black Han Sans",Jua,sans-serif;font-size:12.5px;padding:2px 10px;border-radius:99px;background:#0B2C4A;color:#fff;box-shadow:0 2px 0 rgba(0,0,0,.2)}
.svup{max-width:460px;text-align:center;display:grid;gap:14px}
.svuph{display:grid;justify-items:center;gap:2px}
.svuph h3{margin:0;font-family:"Black Han Sans",Jua,sans-serif;font-weight:400;font-size:32px;color:#fff;-webkit-text-stroke:6px #0B2C4A;paint-order:stroke fill;text-shadow:0 3px 0 rgba(6,30,52,.4)}
.svuph p{margin:0;font-size:15px;color:#34505F}
.svlv{font-family:"Black Han Sans",Jua,sans-serif;font-weight:400;font-size:14px;padding:2px 12px;border-radius:99px;background:#7CFF6B;color:#0B2C4A;box-shadow:inset 0 0 0 2px #0B2C4A}
.svlist{display:grid;gap:12px}
.svc{display:grid;grid-template-columns:52px minmax(0,1fr);column-gap:12px;align-items:center;text-align:left;padding:13px 14px;border-radius:18px;border:3px solid #0B2C4A;background:#fff;box-shadow:0 4px 0 #0B2C4A;font:inherit;color:#0B2C4A;cursor:pointer;position:relative;animation:svcIn .28s cubic-bezier(.3,1.5,.5,1) both}
.svc:nth-child(2){animation-delay:.06s}.svc:nth-child(3){animation-delay:.12s}
@keyframes svcIn{from{transform:scale(.85);opacity:0}to{transform:none;opacity:1}}
.svc:active{transform:translateY(3px);box-shadow:0 1px 0 #0B2C4A}
.svc.new{background:linear-gradient(180deg,#FFFBEA,#FFEAA0)}
.svc.pas{background:linear-gradient(180deg,#F3FBFF,#D2EEFF)}
.svc-ico svg{width:52px;height:52px;display:block}
.svc-tx{display:grid;gap:3px;min-width:0}
.svc-tx b{font-family:"Black Han Sans",Jua,sans-serif;font-weight:400;font-size:20px;line-height:1.15}
.svc-tx small{font-size:14px;line-height:1.35;color:#34505F;word-break:keep-all;overflow-wrap:anywhere}
.svc-tag{position:absolute;top:-11px;right:12px;font-style:normal;font-family:"Black Han Sans",Jua,sans-serif;font-size:12.5px;padding:2px 10px;border-radius:99px;background:#0B2C4A;color:#fff}
.svc.new .svc-tag{background:#E5383B}
.svbuild{display:flex;flex-wrap:wrap;justify-content:center;gap:8px}
.svb{position:relative;width:38px;height:38px}.svb svg{width:38px;height:38px;display:block}
.svb b{position:absolute;right:-5px;bottom:-5px;min-width:18px;height:18px;padding:0 4px;box-sizing:border-box;border-radius:9px;background:#0B2C4A;color:#fff;font-size:11.5px;line-height:18px;text-align:center;font-weight:400;font-family:"Black Han Sans",Jua,sans-serif}
.svbtns{display:grid;grid-template-columns:1.4fr 1fr;gap:8px}.svbtns .btn{min-height:54px;white-space:nowrap}
.svres .crhero .crsub{margin:0;font-family:"Black Han Sans",Jua,sans-serif;font-size:16px;color:#FFF6B0}
@media (orientation:landscape) and (max-height:560px){
  .svup{max-width:min(860px,96vw);gap:10px}.svuph h3{font-size:26px}
  .svlist{grid-template-columns:repeat(3,minmax(0,1fr))}
  .svc{grid-template-columns:1fr;justify-items:center;text-align:center;row-gap:6px;padding:16px 10px 14px}
  .svc-tx small{font-size:13px}
}
.updnotes{margin:2px 0 4px;padding:10px 12px 10px 28px;border-radius:12px;background:rgba(255,255,255,.55);font-size:13.5px;line-height:1.45;color:#24486A;max-height:30vh;overflow-y:auto;word-break:keep-all}

