#svUp{z-index:46}#svRes{z-index:40}
#svCh{z-index:41}#svBox{z-index:46}
.svrr{justify-self:center;min-height:44px;padding:8px 22px;font-size:16px}
.svc-evo{text-decoration:none;font-size:12.5px;color:#B5651D;font-family:"Black Han Sans",Jua,sans-serif}
#svChBtn.dot{position:relative}#svChBtn.dot::after{content:'';position:absolute;top:6px;right:8px;width:11px;height:11px;border-radius:50%;background:#E5383B;box-shadow:0 0 0 2px #fff}
.crchip.box{background:#FFE9C2;box-shadow:inset 0 0 0 2px rgba(184,100,0,.45)}
.svch{max-width:480px;display:grid;gap:12px}
.svch .head{display:flex;align-items:center;gap:8px}.svch .head .tag{margin-right:auto}
.svchx{flex:none;width:42px;height:42px;border-radius:50%;border:3px solid #0B2C4A;background:#fff;font:700 18px/1 sans-serif;color:#0B2C4A;cursor:pointer;box-shadow:0 3px 0 #0B2C4A;display:grid;place-items:center;padding:0}
.svch-lead{margin:0;font-size:14px;color:#34505F;text-align:center;word-break:keep-all}
.svch-list{display:grid;gap:14px}
.svchc{display:grid;gap:12px;padding:14px 14px 14px;border-radius:20px;border:3px solid #0B2C4A;background:linear-gradient(180deg,var(--c1),var(--c2));box-shadow:0 4px 0 #0B2C4A;color:#fff}
.svchc.lock{filter:grayscale(.75) brightness(.85)}
.svch-h{display:flex;align-items:center;gap:10px}
.svch-t{display:grid;gap:2px;min-width:0;flex:1}
.svch-t b{font-family:"Black Han Sans",Jua,sans-serif;font-weight:400;font-size:clamp(19px,5.6vw,23px);-webkit-text-stroke:5px #0B2C4A;paint-order:stroke fill;word-break:keep-all}
.svch-t small{font-size:13.5px;color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.45)}
.svch-pic{flex:none;filter:drop-shadow(0 2px 2px rgba(0,0,0,.35))}
.svch-pr{position:relative;height:56px;margin:0 22px 0 4px}
.svch-bar{position:absolute;left:0;right:0;top:14px;height:12px;border-radius:99px;background:rgba(6,30,52,.45);box-shadow:inset 0 0 0 2px rgba(255,255,255,.25);overflow:hidden}
.svch-bar i{display:block;height:100%;background:linear-gradient(180deg,#FFE45C,#F5A400)}
.svbox{position:absolute;top:0;transform:translateX(-50%);width:40px;height:56px;padding:0;border:0;background:none;display:grid;justify-items:center;align-content:start;gap:1px;cursor:pointer;font:inherit;color:#fff}
.svbox svg{width:38px;height:38px;filter:grayscale(1) brightness(.85);opacity:.85}
.svbox span{font-size:11.5px;font-family:"Black Han Sans",Jua,sans-serif;text-shadow:0 1px 2px rgba(0,0,0,.6);white-space:nowrap}
.svbox.ready svg{filter:none;opacity:1;animation:svbob .9s ease-in-out infinite}
.svbox.ready::after{content:'';position:absolute;top:0;right:0;width:10px;height:10px;border-radius:50%;background:#E5383B;box-shadow:0 0 0 2px #fff}
.svbox.got svg{filter:grayscale(.2);opacity:.45}
@keyframes svbob{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}
.svch-go{min-height:52px;font-size:20px}
.svboxp{max-width:400px;text-align:center;display:grid;gap:12px;justify-items:center}
.svbox-ico svg{width:88px;height:88px;animation:svpop .5s cubic-bezier(.3,1.6,.5,1) both}
@keyframes svpop{from{transform:scale(.4) rotate(-12deg)}to{transform:none}}
.svboxp h3{margin:0;font-family:"Black Han Sans",Jua,sans-serif;font-weight:400;font-size:30px;color:#fff;-webkit-text-stroke:6px #0B2C4A;paint-order:stroke fill}
.svboxp.evo h3{color:#FFE45C}
.svbox-list{list-style:none;margin:0;padding:0;display:grid;gap:8px;width:100%}
.svbox-list li{display:grid;grid-template-columns:44px 1fr;gap:10px;align-items:center;text-align:left;padding:8px 12px;border-radius:14px;background:#fff;box-shadow:inset 0 0 0 2px rgba(11,44,74,.15);animation:svcIn .3s both}
.svbox-list li.evo{background:linear-gradient(180deg,#FFF6CC,#FFE07A);box-shadow:inset 0 0 0 2.5px #C98A00}
.svbox-list li i svg{width:44px;height:44px;display:block}
.svbox-list li span{display:grid;gap:2px}.svbox-list b{font-family:"Black Han Sans",Jua,sans-serif;font-weight:400;font-size:18px;color:#0B2C4A}.svbox-list small{font-size:13.5px;color:#34505F;word-break:keep-all}
#svBoxOk{min-width:180px;min-height:52px;font-size:20px}
.svb.evo svg{filter:drop-shadow(0 0 4px #FFD23F)}
@media (orientation:landscape) and (max-height:560px){.svch{max-width:min(920px,96vw)}.svch-list{grid-template-columns:repeat(3,minmax(0,1fr))}.svch-t b{font-size:18px}.svch-pic{width:70px;height:auto}}
.mpick>.mcard.surv{grid-column:1/-1}

