.svbtns{display:grid;grid-template-columns:1.3fr 1fr 1fr;gap:8px}.svbtns .btn{min-height:54px;white-space:nowrap;min-width:0;padding:6px 8px;font-size:clamp(15px,4.4vw,19px)}
