.svf-nav{width:44px;height:44px;border-radius:50%;border:3px solid #0B2C4A;background:#EAF7FF;font:700 26px/1 sans-serif;color:#0B2C4A;cursor:pointer;box-shadow:0 3px 0 #0B2C4A;padding:0 0 3px}
.svf-mid{display:flex;align-items:center;gap:10px;min-width:0}.svf-pic{flex:none}
.svf-tx{display:grid;gap:2px;min-width:0}.svf-tx b{font-family:"Black Han Sans",Jua,sans-serif;font-weight:400;font-size:18px;color:#0B2C4A;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.svf-tx small{display:flex;align-items:center;gap:4px;font-size:12.5px;color:#34505F;line-height:1.3}.svf-ico svg{width:22px;height:22px;display:block}
.svch-tools{display:grid;grid-template-columns:auto 1fr;gap:10px;align-items:center}.svtr-btn{min-height:44px;padding:6px 16px;font-size:16px;white-space:nowrap}.svch-tools .svch-lead{text-align:left;font-size:13px}
.svtrp{max-width:480px;display:grid;gap:10px}.svtrp .head{display:flex;align-items:center;gap:8px}.svtrp .head .tag{margin-right:auto}
.svtr-pearl{font-family:"Black Han Sans",Jua,sans-serif;font-weight:400;font-size:15px;color:#8A5A00;background:#FFF4C8;border-radius:99px;padding:3px 12px}
