.svtr-tx{display:grid;gap:1px;min-width:0}.svtr-tx b{font-family:"Black Han Sans",Jua,sans-serif;font-weight:400;font-size:17px;color:#0B2C4A}.svtr-tx small{font-size:13px;color:#34505F;word-break:keep-all}
.svtr-lv{font-style:normal;font-size:12px;letter-spacing:2px;color:#F5A400}
