.svch-tools{grid-template-columns:auto auto 1fr}
.svch-go2{display:grid;grid-template-columns:1fr auto;gap:8px}.svch-inf{min-height:52px;font-size:18px;padding:6px 16px;background:linear-gradient(180deg,#B69CFF,#6A4BD8)!important;white-space:nowrap}
.svch-infrec{margin-top:-6px;text-align:right;font-size:12.5px;color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.5)}
.svach-tabs{display:flex;gap:6px;margin-right:auto}.svach-tabs button{font:inherit;font-family:"Black Han Sans",Jua,sans-serif;font-size:16px;padding:7px 14px;border-radius:99px;border:2.5px solid #0B2C4A;background:#fff;color:#0B2C4A;cursor:pointer}
.svach-tabs button[aria-pressed="true"]{background:#0B2C4A;color:#fff}
.svach-bar{display:block;height:6px;border-radius:9px;background:rgba(11,44,74,.12);overflow:hidden;margin-top:3px}.svach-bar u{display:block;height:100%;background:linear-gradient(90deg,#7CFF6B,#2EAA5C)}
.svtr-list li.got{opacity:.55}.svtr-buy.ready{animation:svbob 1s ease-in-out infinite}
.svcx-h{margin:6px 0 2px;font-family:"Black Han Sans",Jua,sans-serif;font-weight:400;font-size:16px;color:#0B2C4A}
.svcx{display:grid;grid-template-columns:repeat(auto-fill,minmax(96px,1fr));gap:8px}
.svcx-c{display:grid;justify-items:center;gap:2px;text-align:center;padding:8px 6px;border-radius:14px;background:#fff;box-shadow:inset 0 0 0 2px rgba(11,44,74,.12)}
.svcx-c i svg{width:40px;height:40px;display:block}.svcx-c b{font-family:"Black Han Sans",Jua,sans-serif;font-weight:400;font-size:14px;color:#0B2C4A;word-break:keep-all}.svcx-c small{font-size:11px;color:#5A6B78;line-height:1.25;word-break:keep-all}
.svcx-c.off i svg{filter:grayscale(1);opacity:.5}
.pzsv{margin:0 0 4px}
#svAchBtn.dot{position:relative}#svAchBtn.dot::after{content:'';position:absolute;top:4px;right:6px;width:10px;height:10px;border-radius:50%;background:#E5383B;box-shadow:0 0 0 2px #fff}
.svfish{display:grid;grid-template-columns:44px 1fr 44px;gap:8px;align-items:center;padding:8px;border-radius:18px;background:#fff;box-shadow:inset 0 0 0 2.5px rgba(11,44,74,.15)}

