function svUltKind(L){return SV_ULTK[svTrait(L)]||'tide'}
function svUltDm(){return 90*(1+SV.lv/30)}
function svUltFx(dt){var i,e,dm=svUltDm();
  if(SV.dash){var D=SV.dash;D.t-=dt;var st=SV.ref*4.2*dt;P.x+=Math.cos(D.a)*st;P.y=clamp(P.y+Math.sin(D.a)*st,SV.y0,SV.y1);P.ang=D.a;if(Math.random()<.6)fxs.push({x:P.x,y:P.y,vy:0,r:P.s*.3,life:.35,col:'#E8FCFF'});
    for(i=0;i<SV.en.length;i++){e=SV.en[i];if(e.dead||e.hits.dash===SV.dashId)continue;if(Math.hypot(e.x-P.x,e.y-P.y)<P.s*.8+e.s*.6){e.hits.dash=SV.dashId;svHurt(e,dm*(e.E.boss?2.5:2),e.x-P.x,e.y-P.y,e.E.boss?0:700)}}
    if(D.t<=0){SV.dash=null;svBlast(190,dm,dm*1.5,'200,240,255')}}
  if(SV.fort>0){SV.fort-=dt;SV.inv=Math.max(SV.inv,.2);var R=P.s*2.4+70;SV.fortTk=(SV.fortTk||0)-dt;var tk=SV.fortTk<=0;if(tk)SV.fortTk=.3;
    for(i=0;i<SV.en.length;i++){e=SV.en[i];if(e.dead)continue;var dx=e.x-P.x,dy=e.y-P.y,d=Math.hypot(dx,dy)||1;if(d<R+e.s*.5){if(!e.E.boss){e.x=P.x+dx/d*(R+e.s*.5);e.y=P.y+dy/d*(R+e.s*.5)}if(tk)svHurt(e,dm*.35,dx,dy,e.E.boss?0:200)}}
    for(i=SV.eb.length-1;i>=0;i--)if(Math.hypot(SV.eb[i].x-P.x,SV.eb[i].y-P.y)<R)SV.eb.splice(i,1)}
  if(SV.big>0){SV.big-=dt;if(SV.big<=0){SV.big=0;svGrow()}}
  if(SV.hide>0)SV.hide-=dt}
function svUltGo(){var k=SV.ultK||'tide',dm=svUltDm(),i,e;
  if(k==='dash'){var a=P.ang;if(keys&&(keys.a||keys.d||keys.w||keys.s)){a=Math.atan2((keys.s?1:0)-(keys.w?1:0),(keys.d?1:0)-(keys.a?1:0))}else if(Math.hypot(P.vx||0,P.vy||0)>20)a=Math.atan2(P.vy,P.vx);SV.dashId=(SV.dashId||0)+1;SV.dash={t:.6,a:a};SV.inv=Math.max(SV.inv,1.3);buzz([20,20,60]);banner(T('돌진!'),'')}
  else if(k==='fort'){SV.fort=4;SV.hp=Math.min(SV.maxHp,SV.hp+1);texts.push({x:P.x,y:P.y-P.s*1.5,txt:'♥ +1',life:.9});rings.push({x:P.x,y:P.y,r:P.s*3,life:.5,max:.5,col:'190,245,255'});buzz([30,30,30])}
  else if(k==='gulp'){SV.big=6;svGrow();svMagnetAll();var R=viewR()*.7,n=0;for(i=0;i<SV.en.length;i++){e=SV.en[i];if(e.dead||!svEdible(e))continue;if(Math.hypot(e.x-P.x,e.y-P.y)<R){fxs.push({x:e.x,y:e.y,vx:(P.x-e.x)*3,vy:(P.y-e.y)*3,r:e.s*.5,life:.3,col:'#7CFF6B'});svKill(e,true);n++}}P.chomp=1;texts.push({x:P.x,y:P.y-P.s*1.6,txt:T('꿀꺽 ')+n,life:1});rings.push({x:P.x,y:P.y,r:R,life:.5,max:.5,col:'124,255,107'});buzz([40,30,60])}
  else if(k==='cloud'){SV.pools.push({x:P.x,y:clamp(P.y,SV.y0,SV.y1),r:260,t:5,max:5,dm:dm*.18,tk:0,seed:Math.random()*6,pull:true});SV.hide=3;rings.push({x:P.x,y:P.y,r:260,life:.5,max:.5,col:'120,90,200'});buzz([30,30,60])}
  else if(k==='storm'){var R2=viewR(),list=SV.en.filter(function(q){return !q.dead&&Math.hypot(q.x-P.x,q.y-P.y)<R2});list.sort(function(a,b){return (b.E.boss?1e9:b.hp)-(a.E.boss?1e9:a.hp)});list=list.slice(0,14);
    list.forEach(function(q,j){setTimeout(function(){if(q.dead||!P.surv)return;SV.zap.push({p:[[q.x+rnd(-40,40),q.y-420],[q.x+rnd(-30,30),q.y-200],[q.x,q.y]],life:.35});svHurt(q,dm*(q.E.boss?2.5:2.2),0,0,0);rings.push({x:q.x,y:q.y,r:q.s*1.2,life:.3,max:.3,col:'185,243,255'})},j*60)});flashT=.2;buzz([20,20,20,20,60])}
  else{svBlast(viewR()*1.1,90,260);svMagnetAll()}}
function svUltDraw(){if(SV.fort>0){var R=P.s*2.4+70,tt=performance.now()/1000;ctx.save();ctx.globalAlpha=Math.min(1,SV.fort*2)*.25;ctx.beginPath();ctx.arc(P.x,P.y,R,0,Math.PI*2);ctx.fillStyle='#BFF4FF';ctx.fill();ctx.globalAlpha=Math.min(1,SV.fort*2)*.9;ctx.lineWidth=5/zoom;ctx.strokeStyle='#E8FCFF';ctx.stroke();ctx.lineWidth=7/zoom;ctx.beginPath();ctx.arc(P.x,P.y,R*.85,-2.5+Math.sin(tt)*.1,-1.6);ctx.stroke();ctx.restore()}
  if(SV.big>0){ctx.save();ctx.globalAlpha=.35+.15*Math.sin(performance.now()/90);ctx.drawImage(glow('124,255,107'),P.x-P.s*1.8,P.y-P.s*1.8,P.s*3.6,P.s*3.6);ctx.restore()}}
