else if(H.k==='beam'){var hz=Math.random()<.6,nb=1+(SV.t>240?1:0)+(SV.t>480?1:0);for(i=0;i<nb;i++){var off=(i-(nb-1)/2)*240+rnd(-60,60);if(hz)SV.tg.push({k:'line',x:P.x-SV_VIEW*1.3,y:clamp(P.y+off,SV.y0,SV.y1),a:0,len:SV_VIEW*2.6,w:64,t:1.5,max:1.5,en:dmg*1.5,beam:1});else SV.tg.push({k:'line',x:P.x+off,y:P.y-SV_VIEW*1.3,a:Math.PI/2,len:SV_VIEW*2.6,w:64,t:1.5,max:1.5,en:dmg*1.5,beam:1})}}
