else if(E.k==='shoal'){E.c=(E.c||0)+dt;var sR=viewR();while(E.c>.07&&E.t>1.5){E.c-=.07;var kr=svSpawn('krill',null,10);if(kr){kr.x=P.x-E.dir*sR*1.15;kr.y=clamp(P.y+rnd(-.55,.55)*sR,SV.y0,SV.y1);kr.wa=E.dir>0?0:Math.PI;kr.v*=5;kr.wob=0;kr.s*=1.5}}}
else if(E.k==='rain'){E.c=(E.c||0)+dt;var R=viewR();while(E.c>.09){E.c-=.09;var ra=Math.random()*Math.PI*2,rd=R*rnd(.15,.85);svDrop(P.x+Math.cos(ra)*rd,clamp(P.y+Math.sin(ra)*rd,SV.y0,SV.y1),Math.max(1,Math.round(SV.lv/6)))}}

var ks=Object.keys(SV_EV).filter(function(k){return k!==SV.evLast}),k=ks[Math.floor(Math.random()*ks.length)];SV.evLast=k;svStAdd('evn',1);var D=SV_EV[k];SV.ev={k:k,t:D.t,max:D.t,dir:Math.random()<.5?-1:1};
if(k==='treasure'){var ta=Math.random()*Math.PI*2,td=viewR()*.55;SV.gem.push({x:P.x+Math.cos(ta)*td,y:clamp(P.y+Math.sin(ta)*td,SV.y0+30,SV.y1-30),v:0,chest:1,s:19,t:0});SV.bonus=(SV.bonus||0)+20;rings.push({x:P.x+Math.cos(ta)*td,y:P.y+Math.sin(ta)*td,r:60,life:.8,max:.8,col:'255,220,90'})}
if(k==='jelly'){var a0=Math.random()*Math.PI*2;for(var j=0;j<16;j++){var m=svSpawn('jelly',a0+rnd(-.5,.5),viewR()*rnd(1.0,1.3));if(m){m.wa=Math.atan2(P.y-m.y,P.x-m.x)+rnd(-.4,.4)}}}

