var SV_PT_MAX=12*3600e3,SV_PT_MIN=5*60e3,SV_PT_ADN=2,SV_PT_ADH=2;
function svPtS(){var S=svSave();if(!S.pt)S.pt={t:Date.now(),ad:'',an:0};if(S.pt.ad!==today()){S.pt.ad=today();S.pt.an=0}return S.pt}
function svPtTop(){var h=0;for(var n=1;n<SV_CH.length;n++)if(svChS(n).clear)h=n;return h}
function svPtOpen(){return (svSave().plays||0)>0}
function svPtRate(){var h=svPtTop();return {p:pkP(20+12*h),g:h>=2}}
function svPtCalc(ms){var R=svPtRate(),hr=clamp(ms,0,SV_PT_MAX)/3600e3;return {p:Math.floor(R.p*hr),g:R.g?Math.floor(hr/4):0,eq:Math.floor(hr/6),hr:hr}}
function svPtTx(r){var a=[T('진주 ')+nf(r.p)];if(r.g)a.push(T('보석 ')+r.g);if(r.eq)a.push(T('장비 ')+r.eq);return a.join(' · ')}
function svPtGive(r){save.pearls+=r.p;if(r.g)save.gems=(save.gems||0)+r.g;var it=[];for(var i=0;i<r.eq;i++)it.push(svEqRoll(Math.max(1,svPtTop())));if(it.length)svEqAdd(it);svStAdd('ptn',1);persist();buzz([20,30,40]);try{refreshHome()}catch(x){}}
function svPtEl(){var o=svPtS(),ms=Math.max(0,Date.now()-(o.t||Date.now())),r=svPtCalc(ms),full=ms>=SV_PT_MAX,h=Math.floor(Math.min(ms,SV_PT_MAX)/3600e3),m=Math.floor(Math.min(ms,SV_PT_MAX)%3600e3/60e3);return {o:o,ms:ms,r:r,full:full,tm:(LANG==='en'?h+'h '+m+'m':h+T('시간 ')+m+T('분'))}}
function svPtClaim(){var E=svPtEl();if(E.ms<SV_PT_MIN){banner(T('조금만 더 기다려요'),T('5분 이상 탐사하면 받을 수 있어요'));return}E.o.t=Date.now();svPtGive(E.r);banner(T('탐사선이 돌아왔어요!'),svPtTx(E.r));svChRender()}
function svPtAd(b){var o=svPtS();if(o.an>=SV_PT_ADN||ADS.busy)return;b.disabled=true;b.textContent=T('광고 불러오는 중…');
  showRewarded(function(ok){var o2=svPtS();if(ok&&o2.an<SV_PT_ADN){o2.an++;var r=svPtCalc(SV_PT_ADH*3600e3);svPtGive(r);banner(T('빠른 탐사 완료!'),svPtTx(r))}else if(!ok)banner(T('광고를 끝까지 보면 받을 수 있어요'),'');svChRender()})}
