var NEWS_LEAD={'1.1.8':T('싱글에 「심해 생존」 시험판이 생겼어요!'),'1.1.7':T('더 깊이 내려갈수록 더 크게 자라요!'),'1.1.6':T('싱글 버튼을 눌러 「심해 탐험」을 골라 보세요!'),'1.1.5':T('좋은 피드백 주신 괭이여왕님 감사합니다! 말씀해 주신 점을 적극 반영해서 업데이트했어요. 제발 돌아와 주세요ㅠㅠ 돌아와 줘 제발…')};
var NEWS={'1.1.8':[T('플레이 › 심해 생존: 저절로 공격하며 몰려오는 물고기 떼를 10분 버텨요'),T('레벨이 오르면 몸이 커지고 · 나보다 작은 물고기는 꿀꺽! 25마리마다 꺼-억으로 하트 회복'),T('도감 물고기로 출전 · 물고기마다 시작 무기 · 특성 · 필살기가 다르고 숙련이 쌓여요'),T('무기 16종 · 능력 11종 · 각성 16종 · 장비 16종(같은 장비 3개를 합쳐 전설까지)'),T('챕터 6개 · 챕터마다 다른 보스 공격과 바다 위험(다시마 덤불 · 낙석 · 폭발 통 · 빛줄기 · 열수구) · 바다 사건'),T('오늘의 도전 · 보스 러시 · ∞ 무한 · ★ 어려움 · 도전 과제 22개 · 무기 · 보스 도감'),T('짝꿍 물고기 5종 · 판마다 고르는 심해의 축복 8종 · 오늘의 임무 · 생존 훈련'),T('시험판이에요 · 재미있었는지 문의하기로 알려 주세요')],'1.1.7':[T('이제 커질수록 얕은 바다 먹이가 작아져요 · 더 크게 자라려면 깊이 내려가세요'),T('가끔 아래쪽에 먹이 떼가 나타나요 · 금색 화살표를 따라가 먹으면 2.5배로 자라요'),T('얕은 바다에서 너무 커지면 갈매기가 내리꽂아요 · 빨간 원이 뜨면 피하세요'),T('물고기마다 사는 깊이가 달라서 깊이 갈수록 크고 맛있는 먹이가 많아요'),T('수족관에 집을 짓고 먹이를 줘요 · 집에서 시간마다 진주가 솟아요'),T('바다 연구 6종·부스터 6종 추가 · 효과는 조금 낮추고 가격은 올렸어요'),T('처음 하는 분을 위한 프롤로그 추가 · 설정에서 다시 볼 수 있어요'),T('게임 중 위쪽 칸을 투명하게 · 일시정지에 설정 버튼'),T('대전 끊김을 줄이고 결과 화면 설명을 읽기 쉽게 다듬었어요'),T('홈 화면 부스터를 한 줄로 정리했어요 · 누르면 켜고 끄는 창이 열려요'),T('알림: 수족관 집 진주가 가득 차거나 먹이 줄 시간이면 알려 줘요(밤 0~8시 제외) · 먹을 때 톡 진동도 이제 제대로 나요')],'1.1.6':[T('새 모드 「심해 탐험」: 1~30층 목표를 깨며 바다 아래로 내려가요'),T('물어뜯기가 돌아왔어요: 큰 물고기의 입을 피해 몸통을 물면 작아지고 나는 자라요'),T('대전: 나보다 작은 사람 물고기를 확실히 먹을 수 있어요(5%만 작아도 돼요)'),T('층마다 먹기·크기·사냥·버티기 목표 · 별을 모아 탐험 랭킹에 도전해요'),T('10·20·30층에는 보스가 기다려요 · 보스를 먹으면 보석 5개'),T('탐험할 때마다 아직 없는 꾸미기를 무작위로 입어 봐요'),T('처음 깬 층은 에너지를 돌려받고 · 별 10개마다 보석 3개'),T('진주 균형 조정: 판에서 받는 진주가 조금 줄고 진주 상품 가격이 올랐어요'),T('위쪽 칸을 한 줄로 줄이고 조작 버튼을 반투명하게 해서 시야를 넓혔어요'),T('점수 목표·보물상자 글자 모으기는 빠졌어요 · 그 진주는 점수만큼 그대로 받아요'),T('미션이 오늘·주간·월간으로 늘었어요 · 다 한 미션은 금색으로 맨 위에'),T('게임 중에도 설정 버튼으로 조이스틱 좌우·소리를 바로 바꿔요(대전 포함)'),T('광고·탐험 지도를 볼 때 메모리를 덜 써서 갑자기 꺼지는 문제를 더 줄였어요')],'1.1.5':[T('대전에서 나보다 작은 상대를 확실히 먹을 수 있어요'),T('먹을 때 귀여운 효과음과 톡 하는 진동이 생겼어요'),T('배경음악은 이제 꺼진 채로 시작해요 · 설정 › 소리에서 켤 수 있어요'),T('갑자기 꺼지는 문제를 줄였어요 · 그래도 끊기면 설정 › 성능 › 가벼운 모드'),T('규칙을 단순하게: 나보다 작은 물고기만 먹어요'),T('새 물고기 10종 · 물고기 꾸미기 90종 추가')]};
